{
  "call_911_if": [
    {
      "id": "b1",
      "text": "Call 911 or go to the emergency room if you have chest pain or sudden shortness of breath.",
      "sources": ["p1:L14", "term:ED"]
    },
    {
      "id": "b2",
      "text": "Call the surgeon if you have calf pain or swelling in either leg.",
      "sources": ["p1:L15", "p1:L16"]
    },
    {
      "id": "b3",
      "text": "Call the surgeon if you have a fever over 101.5 F.",
      "sources": ["p1:L15", "p1:L17"]
    },
    {
      "id": "b4",
      "text": "Call the surgeon if you have redness, warmth or drainage from the incision.",
      "sources": ["p1:L15", "p1:L18"]
    }
  ]
}
